  {"controlId":"CO-VND-007","processArea":"Vendor and Third-Party Management","processName":"Dependency Vulnerability Review","description":"For all production repositories, the operator periodically reviews package manifests and GitHub dependency insights to identify high-severity vulnerabilities or problematic licenses. Identified issues are triaged with upgrades or replacements tracked to completion. Where immediate remediation is not feasible, a risk acceptance note is documented.","controlObjective":"Ensure third-party dependencies in code repositories are governed and do not introduce unmanaged security or licensing risk.","controlType":"DETECTIVE","controlNature":"MANUAL","controlFrequency":"MONTHLY","keyControl":True},
