  {"controlId":"CO-VND-009","processArea":"Vendor and Third-Party Management","processName":"Cloud Cost Monitoring","description":"The operator configures cost and usage dashboards and alerts for vendor platforms where available. At defined intervals, usage and cost metrics are reviewed for unusual spikes, new regions, or atypical workloads. Where anomalies are identified, the operator investigates, documents findings, and adjusts configuration or usage patterns.","controlObjective":"Detect anomalous or unexpected usage patterns that may indicate misconfiguration, abuse, or cost risk across vendor platforms.","controlType":"DETECTIVE","controlNature":"MANUAL","controlFrequency":"MONTHLY","keyControl":False},
